import { describe, expect, it } from "vitest";
import handler from "../api/extract-emr.js";
import { fail, fixtureBase64, makeReq, makeRes, mockGroq, ok } from "./helpers.js";

// Everything here is synthetic. No real patient data.
const GOOD_AI_REPLY = JSON.stringify({ name: "TEST PATIENT", currentDiagnosis: "Malaria", summary: "Synthetic summary." });

// Fixtures live in tests/fixtures (generated by make_fixtures.py, all invented).
const pdfBody = (fixtureName) => ({
  document: { data: fixtureBase64(fixtureName), mediaType: "application/pdf" },
});

async function run(body, opts) {
  const res = makeRes();
  await handler(makeReq(body, opts), res);
  return res;
}

describe("extract-emr: request validation", () => {
  it("answers CORS preflight", async () => {
    const res = await run(undefined, { method: "OPTIONS" });
    expect(res.statusCode).toBe(204);
  });

  it("rejects non-POST requests", async () => {
    const res = await run(undefined, { method: "GET" });
    expect(res.statusCode).toBe(405);
  });

  it("rejects a request with no document", async () => {
    mockGroq();
    const res = await run({});
    expect(res.statusCode).toBe(400);
    expect(res.json.error).toMatch(/Missing document data/);
  });

  it("rejects more than one PDF", async () => {
    mockGroq();
    const d = { data: "AAAA", mediaType: "application/pdf" };
    const res = await run({ documents: [d, d] });
    expect(res.statusCode).toBe(400);
    expect(res.json.error).toMatch(/Only one PDF/);
  });

  it("rejects an oversized upload with advice about Save as PDF", async () => {
    mockGroq();
    const res = await run({ document: { data: "A".repeat(4.3 * 1024 * 1024), mediaType: "application/pdf" } });
    expect(res.statusCode).toBe(400);
    expect(res.json.error).toMatch(/3MB/);
    expect(res.json.error).toMatch(/Save as PDF/);
  });
});

describe("extract-emr: typed text path", () => {
  it("rejects text that is too short", async () => {
    mockGroq();
    const res = await run({ rawText: "too short" });
    expect(res.statusCode).toBe(400);
  });

  it("sends typed notes to the AI and returns the structured result", async () => {
    const { calls } = mockGroq({}, ok(GOOD_AI_REPLY));
    const text = "Synthetic note: patient admitted with fever, BP 120/80, pulse 88, started on IV artesunate.";
    const res = await run({ rawText: text });
    expect(res.statusCode).toBe(200);
    expect(JSON.parse(res.json.choices[0].message.content).name).toBe("TEST PATIENT");
    expect(calls).toHaveLength(1);
    expect(calls[0].messages[0].content).toContain("IV artesunate");
  });
});

describe("extract-emr: PDF path", () => {
  it("reads a PDF with a text layer and runs the deterministic scans", async () => {
    const { calls } = mockGroq({}, ok(GOOD_AI_REPLY));
    const res = await run(pdfBody("improving.pdf"));
    expect(res.statusCode).toBe(200);
    expect(res.json.prognosisTrend).toBe("IMPROVING");
    expect(res.json.filteredText).toContain("[PRIMARY DIAGNOSIS SCAN");
    expect(res.json.filteredText).toContain("malaria");
    expect(calls).toHaveLength(1); // exactly one AI call per extraction
    expect(calls[0].messages[0].content).toContain("PROGNOSIS TREND");
  });

  it("detects a deteriorating trend", async () => {
    mockGroq({}, ok(GOOD_AI_REPLY));
    const res = await run(pdfBody("deteriorating.pdf"));
    expect(res.json.prognosisTrend).toBe("DETERIORATING");
  });

  it("resolves surgery name and post-operative day", async () => {
    mockGroq({}, ok(GOOD_AI_REPLY));
    const res = await run(pdfBody("surgery.pdf"));
    expect(res.json.dpoDay).toBe("2");
    expect(res.json.surgeryName).toMatch(/Laparotomy/i);
  });

  it("explains how to fix a PDF that has no readable text", async () => {
    mockGroq({}, ok(GOOD_AI_REPLY));
    const res = await run(pdfBody("blank.pdf")); // a PDF page with no text, like a picture-only export
    expect(res.statusCode).toBe(500);
    expect(res.json.error).toMatch(/No readable text found/);
    expect(res.json.error).toMatch(/Save as PDF/);
  });

  it("returns a JSON error (not a crash) when the AI service rejects the request", async () => {
    mockGroq({}, fail(401, "invalid_api_key", "Invalid API Key"));
    const res = await run(pdfBody("improving.pdf"));
    expect(res.statusCode).toBe(500);
    expect(res.json.error).toMatch(/Extraction failed: Invalid API Key/);
  });

  it("returns a JSON error when the AI answers with something unreadable", async () => {
    mockGroq({}, ok("I am sorry, I cannot help with that."));
    const res = await run(pdfBody("improving.pdf"));
    expect(res.statusCode).toBe(500);
    expect(res.json.error).toMatch(/unreadable data/);
  });
});
